import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
K=['RSPP-A','RSPP-AGG']
EA(K,'ZR62','Dalla tutela reattiva alla prevenzione organizzata',[LB("Laboratorio · Da reattivo a preventivo","Analizzi come un’impresa di 70 lavoratori gestisce oggi la sicurezza e proponi il passaggio a un approccio preventivo.",[
  ["Oggi","si interviene dopo gli infortuni; il DVR è un documento redatto una volta e archiviato; i quasi incidenti non si registrano"],["Risorse","RSPP esterno 8 giorni l’anno; preposti non formati"],["Obiettivo della direzione","ridurre gli infortuni del 30% in due anni"]],[
  ("Quali segnali indicano un approccio reattivo?",6,"Interventi solo dopo gli eventi; DVR statico e non usato; assenza di dati sui quasi incidenti; preposti non formati; nessun indicatore proattivo.",["Ho elencato i segnali reattivi"]),
  ("Proponi cinque azioni per un approccio preventivo.",8,"Registrazione e analisi dei quasi incidenti; DVR come strumento vivo con programma delle misure monitorato; formazione e individuazione dei preposti; sopralluoghi periodici della direzione; riunioni brevi di reparto e indicatori proattivi.",["Ho proposto azioni organizzative","Ho collegato DVR e programma","Ho previsto indicatori proattivi"],None,120),
  ("Come misuri il raggiungimento dell’obiettivo?",6,"Indice di frequenza e numero di infortuni rispetto all’anno base, insieme a indicatori proattivi come quasi incidenti segnalati e azioni chiuse: la riduzione degli infortuni deve essere accompagnata da una crescita delle attività preventive.",["Ho indicato l’indicatore di risultato","Ho collegato indicatori proattivi"])],
 "Nel laboratorio analizzi un’impresa che gestisce la sicurezza in modo reattivo e proponi il passaggio a un approccio preventivo, con azioni e indicatori. Confronta ogni risposta con la soluzione di riferimento.","Art. 15 D.lgs. 81/2008 · UNI EN ISO 45001")])
EA(K,'ZR63','La responsabilità amministrativa degli enti',[SC("L’interesse dell’ente","Per rispettare una consegna, il direttore di produzione autorizza a lavorare con una pressa senza la barriera fotoelettrica, guasta da giorni. Un operaio si ferisce gravemente.",[
 ("C’è interesse o vantaggio dell’ente?",[["Sì: il risparmio di tempo e il rispetto della consegna sono un vantaggio per l’ente",True,"Corretto: anche il risparmio di tempi o costi integra il criterio."],["No, l’ente non voleva l’infortunio",False,"Non serve volere l’evento."],["Solo se c’è un guadagno in denaro",False,"Basta il risparmio di tempi."]]),
 ("Quale reato presupposto può essere contestato?",[["Lesioni colpose gravi con violazione delle norme di sicurezza, art. 25-septies",True,"Corretto."],["Truffa",False,"Non pertinente."],["Nessuno",False,"È un reato presupposto."]]),
 ("Che cosa avrebbe tutelato l’ente?",[["Un modello organizzativo efficace con procedure di blocco delle macchine guaste, vigilanza e sistema disciplinare",True,"Corretto."],["Una polizza",False,"Non esclude la responsabilità."],["Un cartello",False,"Non basta."]])],
 "Anche un risparmio di tempo è un vantaggio per l’ente: senza un modello efficace, una lesione grave da violazione delle norme di sicurezza coinvolge l’impresa.","Una pressa usata senza barriera per rispettare una consegna. Valuta la responsabilità dell’ente.","D.lgs. 231/2001, artt. 5 e 25-septies")])
EA(K,'ZR64','Il nuovo preposto',[LB("Laboratorio · Il preposto negli appalti","Organizzi l’individuazione dei preposti in un appalto di manutenzione con due imprese esterne.",[
  ["Committente","stabilimento chimico"],["Appaltatore","impresa di manutenzione meccanica con 6 tecnici"],["Subappaltatore","impresa di coibentazione con 3 operai"],["Durata","4 settimane, lavori in quota e a caldo"]],[
  ("Che cosa prevede l’art. 26, comma 8-bis?",6,"Nei contratti di appalto e subappalto i datori di lavoro appaltatori e subappaltatori indicano espressamente al committente il personale che svolge la funzione di preposto.",["Ho citato l’obbligo di indicazione","Ho incluso il subappaltatore"]),
  ("Quali compiti hanno i preposti delle imprese esterne?",7,"Sovrintendere e vigilare sulle proprie squadre, intervenire sui comportamenti non conformi e interrompere l’attività in caso di inosservanza persistente o di pericolo, segnalare deficienze, applicare permessi di lavoro e misure del DUVRI.",["Ho descritto vigilanza e interruzione","Ho collegato permessi e DUVRI"]),
  ("Come coordini i preposti con il committente?",7,"Riunione di coordinamento iniziale con DUVRI e permessi di lavoro; referente del committente; brevi riunioni quotidiane; registro dei permessi; canale per segnalare interferenze e sospendere i lavori.",["Ho previsto la riunione iniziale","Ho previsto permessi e riunioni quotidiane"]),
  ("Come verifichi la loro formazione?",6,"Attestati del corso di 12 ore in presenza o videoconferenza sincrona e degli aggiornamenti biennali; verifica prima dell’ingresso in stabilimento e registrazione.",["Ho indicato corso e aggiornamento","Ho previsto la verifica prima dell’ingresso"])],
 "Nel laboratorio organizzi i preposti in un appalto con subappalto: obbligo di indicazione, compiti, coordinamento con il committente e verifica della formazione. Confronta ogni risposta con la soluzione di riferimento.","Artt. 19 e 26, c. 8-bis, D.lgs. 81/2008 · Accordo 17 aprile 2025")])
EA(K,'ZR65','L\'Accordo Stato-Regioni 17 aprile 2025',[LB("Laboratorio · Adeguare il catalogo corsi all’Accordo 2025","Aggiorni il catalogo dei corsi di un soggetto formatore alle regole dell’Accordo 2025.",[
  ["Catalogo attuale","corsi preposti 8 ore in e-learning; test finale di 10 domande per tutti i corsi; nessun tutor nei corsi online; fascicoli conservati 5 anni"],["Nuovi corsi richiesti","datori di lavoro e ambienti confinati"]],[
  ("Individua le non conformità del catalogo attuale.",7,"Preposti: 12 ore in presenza o videoconferenza sincrona, non 8 ore in e-learning. Test: almeno 30 domande nei corsi base e 10 negli aggiornamenti, soglia 70%. Tutor obbligatorio in e-learning e videoconferenza. Fascicolo conservato 10 anni.",["Ho corretto il corso preposti","Ho corretto test e tutor","Ho corretto la conservazione"]),
  ("Imposta i nuovi corsi.",7,"Datori di lavoro: 16 ore in due moduli, più modulo cantieri di 6 ore per le imprese affidatarie, con aggiornamento quinquennale. Ambienti confinati: 12 ore con parte pratica.",["Ho indicato le durate","Ho previsto il modulo cantieri"]),
  ("Che cosa aggiungi per la verifica di efficacia?",6,"Strumenti per il datore di lavoro: schede di osservazione dei comportamenti dopo il corso, indicatori e riscontro al formatore; documentazione nel fascicolo.",["Ho previsto strumenti di osservazione","Ho previsto la documentazione"])],
 "Nel laboratorio adegui il catalogo di un soggetto formatore all’Accordo 2025: non conformità, nuovi corsi e verifica di efficacia. Confronta ogni risposta con la soluzione di riferimento.","Accordo Stato-Regioni 17 aprile 2025")])
EA(K,'ZR66','Il decreto-legge 159/2025',[SC("Le novità per l’RLS","In un’impresa con 12 lavoratori l’RLS chiede come cambierà il suo aggiornamento e se potrà accedere a risorse per la formazione.",[
 ("Che cosa prevede il decreto per l’aggiornamento dell’RLS nelle imprese sotto i 15 lavoratori?",[["L’aggiornamento è affidato alla contrattazione collettiva",True,"Corretto: art. 37, comma 11."],["È abolito",False,"Non è abolito."],["È di 40 ore annue",False,"Non è la regola."]]),
 ("Dove saranno registrate le competenze?",[["Nel fascicolo elettronico del lavoratore",True,"Corretto: art. 37, comma 14."],["Solo nell’archivio aziendale",False,"È previsto il fascicolo elettronico."],["Nel DVR",False,"Non è la sede."]]),
 ("Esistono risorse per la formazione degli RLS?",[["Sì: risorse INAIL non inferiori a 35 milioni di euro annui, anche per gli RLS aziendali, territoriali e di sito",True,"Corretto."],["No",False,"Il decreto le prevede."],["Solo per le grandi imprese",False,"Non è limitato così."]])],
 "Il D.L. 159/2025 affida alla contrattazione l’aggiornamento dell’RLS nelle piccole imprese, introduce il fascicolo elettronico e destina risorse INAIL alla formazione.","Un RLS chiede delle novità. Rispondi con precisione.","D.L. 159/2025 · art. 37 D.lgs. 81/2008")])
EA(K,'ZR67','La responsabilità penale del RSPP',[LB("Laboratorio · La segnalazione scritta dell’RSPP","Scrivi una segnalazione al datore di lavoro dopo un sopralluogo in cui hai trovato un rischio grave.",[
  ["Rilievo","scaffalatura del magazzino con montante deformato e carichi oltre la portata indicata"],["Contesto","passaggio frequente di carrelli e persone"],["Precedenti","nessuna segnalazione precedente"]],[
  ("Scrivi la descrizione del rischio.",7,"Data, area, descrizione oggettiva: montante della campata 12 deformato da un urto, carichi stimati oltre la portata indicata in targa; possibile crollo con lesioni gravissime per le persone in corsia.",["Ho descritto i fatti con data e luogo","Ho indicato la possibile conseguenza"]),
  ("Indica le misure proposte con urgenza e responsabilità.",7,"Immediata: scarico della campata e interdizione dell’area. Entro una settimana: verifica da parte di persona competente e sostituzione del montante. Poi: protezioni dei montanti, regole di carico, ispezioni periodiche. Decisione e risorse: datore di lavoro.",["Ho distinto misure immediate e successive","Ho indicato chi decide"]),
  ("Come rendi la segnalazione tracciabile ed efficace?",6,"Invio scritto con data certa o ricevuta, richiesta di riscontro entro un termine, copia nell’archivio del servizio, verifica sul posto alla scadenza e annotazione dello stato.",["Ho previsto data certa e riscontro","Ho previsto la verifica successiva"])],
 "Nel laboratorio scrivi la segnalazione dell’RSPP al datore di lavoro su una scaffalatura danneggiata: descrizione del rischio, misure proposte e tracciabilità. Confronta ogni risposta con la soluzione di riferimento.","Art. 33 D.lgs. 81/2008 · Cass. pen., Sezioni Unite, n. 38343/2014")])
EA(K,'ZR68','Cantieri: patente a crediti e badge',[SC("Il badge di cantiere","Un’impresa affidataria apre un cantiere dove lavoreranno quattro imprese subappaltatrici.",[
 ("A che cosa serve il badge di cantiere?",[["A identificare e tracciare le presenze dei lavoratori nel cantiere, rafforzando i controlli",True,"Corretto: introdotto dal D.L. 159/2025."],["A sostituire la tessera di riconoscimento",False,"Si aggiunge agli strumenti esistenti."],["A pagare i lavoratori",False,"Non è la sua funzione."]]),
 ("Che cosa verifichi per ogni subappaltatore?",[["Patente a crediti con almeno 15 crediti, idoneità tecnico-professionale e POS",True,"Corretto."],["Solo il preventivo",False,"Non basta."],["Solo il DURC",False,"È solo uno dei documenti."]]),
 ("Un lavoratore si presenta senza badge e senza tessera. Che cosa fai?",[["Non lo fai entrare finché non è identificato e verificata la sua posizione",True,"Corretto."],["Lo fai entrare se è accompagnato",False,"Va identificato."],["Lo registri a fine giornata",False,"La verifica è all’ingresso."]])],
 "Badge di cantiere, patente a crediti e documenti delle imprese: il controllo degli accessi è la prima misura di legalità e di sicurezza del cantiere.","Un cantiere con quattro subappaltatori. Organizza i controlli di accesso.","Art. 27 D.lgs. 81/2008 · D.L. 159/2025")])
EA(K,'ZR69','Le riforme dal 2021 a oggi',[ES("Esempio guidato · Le riforme dal 2021","Le principali novità per chi si occupa di prevenzione.",[
 ["2021","D.L. 146/2021: preposto rafforzato, competenza estesa dell’Ispettorato, nuova sospensione dell’attività.","Preposto e vigilanza"],
 ["2024","D.L. 19/2024: patente a crediti per i cantieri.","Patente a crediti"],
 ["2025","Accordo Stato-Regioni 17 aprile: riordino della formazione.","Formazione"],
 ["2025","D.L. 159/2025: badge di cantiere, fascicolo elettronico, risorse per gli RLS.","Cantieri e formazione"],
 ["2026","Chiarimenti ministeriali del 27 marzo sulla formazione.","FAQ ministeriali"]],
 "Riepiloghiamo le riforme. Nel duemilaventuno il decreto centoquarantasei rafforza il preposto e la vigilanza. Nel duemilaventiquattro arriva la patente a crediti. Nel duemilaventicinque l’Accordo del diciassette aprile riordina la formazione e il decreto centocinquantanove introduce badge di cantiere e fascicolo elettronico. Nel marzo duemilaventisei il Ministero pubblica i chiarimenti sulla formazione.","D.L. 146/2021 · D.L. 19/2024 · Accordo 2025 · D.L. 159/2025")])
